use super::*;
use liquidbounce_behaviors::nametags::{Part,Slot,Settings};
#[derive(Clone,Debug,PartialEq)]pub struct NametagsSetting(pub String,pub Value);
fn error(p:&str,m:&str)->ConfigError{ConfigError::new(&format!("Nametags.{p}"),m)}
fn color(v:&Value,p:&str)->Result<u32,ConfigError>{if let Some(raw)=v.as_str(){let s=raw.strip_prefix('#').unwrap_or(raw);if !matches!(s.len(),6|8){return Err(error(p,"expected hex RRGGBB or AARRGGBB"));}u32::from_str_radix(s,16).map(|v|if s.len()==6{v|0xff000000}else{v}).map_err(|_|error(p,"invalid color"))}else{v.as_i64().map(|v|v as u32).or_else(||v.as_u64().map(|v|v as u32)).ok_or_else(||error(p,"expected ARGB integer"))}}
fn choices<T:PartialEq>(v:&Value,parse:impl Fn(&str)->Option<T>)->Vec<T>{let list=match v{Value::Array(a)=>a.as_slice(),Value::String(_)|Value::Number(_)|Value::Bool(_)=>std::slice::from_ref(v),_=>&[]};let mut out=vec![];for v in list{if let Some(value)=scalar_string(v).and_then(|s|parse(&s))&& !out.contains(&value){out.push(value);}}out}
impl NametagsSetting{
    pub fn apply(self,s:&mut Settings,registry:&[String])->Result<(),ConfigError>{let Self(p,v)=self;let path=format!("Nametags.{p}");match p.as_str(){
        "Text.Parts"=>{s.parts=choices(&v,Part::parse);if s.parts.is_empty(){s.parts=Part::ALL.to_vec();}},
        "Equipment.Slots"=>s.slots=choices(&v,Slot::parse),
        "Equipment.SkipEmptySlot"=>s.skip_empty=parse_bool(&v,&path)?,"Equipment.ShowInfo"=>s.show_info=parse_bool(&v,&path)?,
        "Equipment.HighlightItemInUse.Enabled"=>s.highlight=parse_bool(&v,&path)?,"Equipment.HighlightItemInUse.FillColor"=>s.fill=color(&v,&p)?,"Equipment.HighlightItemInUse.OutlineColor"=>s.outline=color(&v,&p)?,
        "Equipment.Enchantment.Enabled"=>s.enchantment=parse_bool(&v,&path)?,"Equipment.Enchantment.Scale"=>s.enchantment_scale=parse_float(&v,&path)?,"Equipment.Enchantment.MaxCountPerItem"=>s.max_count=parse_int(&v,&path)?,"Equipment.Enchantment.BackgroundRadius"=>s.enchantment_radius=parse_float(&v,&path)?,
        "Equipment.Enchantment.Filter"=>{s.whitelist=match scalar_string(&v).as_deref(){Some(s)if s.eq_ignore_ascii_case("Whitelist")=>true,Some(s)if s.eq_ignore_ascii_case("Blacklist")=>false,_=>return Err(error(&p,"unknown filter"))};},
        "Equipment.Enchantment.Enchantments"=>{let list=match &v{Value::Array(a)=>a.as_slice(),_=>std::slice::from_ref(&v)};let mut out=std::collections::BTreeSet::new();for v in list{let raw=match v{Value::String(s)=>s.clone(),Value::Number(n)=>n.to_string(),_=>return Err(error(&p,"expected registry primitive"))};let id=match raw.split_once(':'){None=>format!("minecraft:{raw}"),Some(("",name))=>format!("minecraft:{name}"),Some(_)=>raw};if !registry.is_empty()&&!registry.contains(&id){return Err(error(&p,"unknown enchantment identifier"));}out.insert(id);}s.enchantments=out;},
        "BorderWidth"=>s.border_width=parse_float(&v,&path)?,"BackgroundRadius"=>s.background_radius=parse_float(&v,&path)?,
        "Scale"=>s.scale=v.as_array().ok_or_else(||error(&p,"expected curve points"))?.iter().map(|v|Ok([parse_float(&v["x"],&path)?,parse_float(&v["y"],&path)?])).collect::<Result<_,ConfigError>>()?,
        _=>return Err(error(&p,"unknown setting")),
    }Ok(())}
}
fn key(p:&str)->String{format!("liquidbounce.module.nametags.{}",p.split('.').map(|s|s[..1].to_ascii_lowercase()+&s[1..]).collect::<Vec<_>>().join("."))}
pub fn serialize_nametags(s:&Settings,common:&CommonSettings,format:JsonFormat,describe:&dyn Fn(&str)->String)->Result<Value,ConfigError>{
    let t=Tree{format,describe};let leaf=|n:&str,ty:&str,v:Value,p:&str|t.leaf(n,ty,v,&key(p),None);let ranged=|n:&str,ty:&str,v:Value,from:f32,to:f32,p:&str|t.ranged(n,ty,v,if ty=="INT"{json!({"from":from as i32,"to":to as i32})}else{json!({"from":from,"to":to})},"",&key(p));
    let group=|n:&str,ty:&str,values:Vec<Value>,p:&str|{let mut v=t.group(n,ty,values);if format==JsonFormat::Interop{v["key"]=json!(key(p));v["description"]=json!(describe(&format!("{}.description",key(p))));}v};
    let mut parts=leaf("Parts","MULTI_CHOOSE",json!(s.parts.iter().map(|p|p.tag()).collect::<Vec<_>>()),"Text.Parts");let mut slots=leaf("Slots","MULTI_CHOOSE",json!(s.slots.iter().map(|p|p.tag()).collect::<Vec<_>>()),"Equipment.Slots");
    if format==JsonFormat::Interop{for(v,all,none)in[(&mut parts,json!(Part::ALL.map(Part::tag)),false),(&mut slots,json!(Slot::ALL.map(Slot::tag)),true)]{v["choices"]=all;v["canBeNone"]=json!(none);v["isOrderSensitive"]=json!(true);}}
    let mut enchantments=s.enchantments.iter().collect::<Vec<_>>();enchantments.sort_by(|a,b|{let(an,ap)=a.split_once(':').unwrap_or(("minecraft",a));let(bn,bp)=b.split_once(':').unwrap_or(("minecraft",b));ap.cmp(bp).then_with(||an.cmp(bn))});
    let mut entries=leaf("Enchantments","REGISTRY_LIST",json!(enchantments),"Equipment.Enchantment.Enchantments");if format==JsonFormat::Interop{entries["registry"]=json!("enchantment");}
    let mut filter=leaf("Filter","CHOOSE",json!(if s.whitelist{"Whitelist"}else{"Blacklist"}),"Equipment.Enchantment.Filter");if format==JsonFormat::Interop{filter["choices"]=json!(["Whitelist","Blacklist"]);}
    let enchantment=group("Enchantment","TOGGLEABLE",vec![leaf("Enabled","BOOLEAN",json!(s.enchantment),"Equipment.Enchantment.Enabled"),ranged("Scale","FLOAT",float_json(s.enchantment_scale,"Scale")?,0.25,4.,"Equipment.Enchantment.Scale"),ranged("MaxCountPerItem","INT",json!(s.max_count),1.,16.,"Equipment.Enchantment.MaxCountPerItem"),ranged("BackgroundRadius","FLOAT",float_json(s.enchantment_radius,"BackgroundRadius")?,0.,8.,"Equipment.Enchantment.BackgroundRadius"),entries,filter],"Equipment.Enchantment");
    let highlight=group("HighlightItemInUse","TOGGLEABLE",vec![leaf("Enabled","BOOLEAN",json!(s.highlight),"Equipment.HighlightItemInUse.Enabled"),leaf("FillColor","COLOR",json!(s.fill as i32),"Equipment.HighlightItemInUse.FillColor"),leaf("OutlineColor","COLOR",json!(s.outline as i32),"Equipment.HighlightItemInUse.OutlineColor")],"Equipment.HighlightItemInUse");
    let mut values=t.common(ModuleKind::Nametags,common);values.push(group("Text","CONFIGURABLE",vec![parts],"Text"));values.push(group("Equipment","CONFIGURABLE",vec![slots,leaf("SkipEmptySlot","BOOLEAN",json!(s.skip_empty),"Equipment.SkipEmptySlot"),leaf("ShowInfo","BOOLEAN",json!(s.show_info),"Equipment.ShowInfo"),enchantment,highlight],"Equipment"));
    values.push(ranged("BorderWidth","FLOAT",float_json(s.border_width,"BorderWidth")?,0.,8.,"BorderWidth"));values.push(ranged("BackgroundRadius","FLOAT",float_json(s.background_radius,"BackgroundRadius")?,0.,16.,"BackgroundRadius"));
    let mut curve=leaf("Scale","CURVE",json!(s.scale.iter().map(|p|json!({"x":p[0],"y":p[1]})).collect::<Vec<_>>()),"Scale");if format==JsonFormat::Interop{curve["innerType"]=json!("VECTOR2_F");curve["xAxis"]=json!({"label":"Distance","range":{"from":0,"to":200}});curve["yAxis"]=json!({"label":"Scale","range":{"from":0.25,"to":4}});curve["tension"]=json!(0.4);}values.push(curve);Ok(t.group("Nametags","TOGGLEABLE",values))
}
fn push(patch:&mut SettingsPatch,p:&str,v:&Value){let c=NametagsSetting(p.into(),v.clone());let registry=v.as_array().into_iter().flatten().filter_map(Value::as_str).map(|s|if s.contains(':'){s.into()}else{format!("minecraft:{s}")}).collect::<Vec<_>>();match c.clone().apply(&mut Settings::default(),&registry){Ok(())=>patch.changes.push(SettingChange::Nametags(c)),Err(e)=>patch.issues.push(e)}}
pub(super) fn parse_nametags(patch:&mut SettingsPatch,root:&Nodes<'_>){
    for n in["BorderWidth","BackgroundRadius","Scale"]{if let Some(v)=root.get(n).and_then(|v|v.get("value")){push(patch,n,v);}}
    for(path,fields)in[("Text",&["Parts"][..]),("Equipment",&["Slots","SkipEmptySlot","ShowInfo"][..]),("Equipment.Enchantment",&["Enabled","Scale","MaxCountPerItem","BackgroundRadius","Enchantments","Filter"][..]),("Equipment.HighlightItemInUse",&["Enabled","FillColor","OutlineColor"][..])]{
        let mut current=root.clone();let mut valid=true;for part in path.split('.'){let Some(v)=current.get(part)else{valid=false;break;};match nodes(v,part,&format!("Nametags.{path}")){Ok(n)=>current=n,Err(e)=>{patch.issues.push(e);valid=false;break;}}}if valid{for field in fields{if let Some(v)=current.get(*field).and_then(|v|v.get("value")){push(patch,&format!("{path}.{field}"),v);}}}
    }
}
#[cfg(test)]mod tests{
    use super::*;
    #[test]fn ordered_choices_and_empty_parts_follow_original(){let mut s=Settings::default();NametagsSetting("Text.Parts".into(),json!(["Name","Distance","name"])).apply(&mut s,&[]).unwrap();assert_eq!(s.parts,[Part::Name,Part::Distance]);NametagsSetting("Text.Parts".into(),json!([])).apply(&mut s,&[]).unwrap();assert_eq!(s.parts,Part::ALL);NametagsSetting("Equipment.Slots".into(),json!(["Boots","Chestplate","Mainhand"])).apply(&mut s,&[]).unwrap();assert_eq!(s.slots,[Slot::Feet,Slot::Chest,Slot::Mainhand]);NametagsSetting("Equipment.Slots".into(),json!([])).apply(&mut s,&[]).unwrap();assert!(s.slots.is_empty());}
    #[test]fn all_nested_groups_roundtrip_when_disabled(){for format in[JsonFormat::File,JsonFormat::Interop]{let mut s=Settings::default();s.parts=vec![Part::TotemPops,Part::Name];s.slots=vec![Slot::Saddle,Slot::Chest,Slot::Body];s.enchantment=false;s.highlight=true;s.enchantment_scale=2.;s.max_count=16;s.enchantment_radius=8.;s.fill=0x40abcdef;s.outline=0xff123456;s.enchantments.insert("fixture:curse".into());s.whitelist=true;s.border_width=8.;s.background_radius=16.;s.scale=vec![[0.,4.],[200.,0.25]];let common=CommonSettings{enabled:false,hidden:false,key_bind:json!({"boundKey":"key.keyboard.unknown","action":"Toggle"})};let v=serialize_nametags(&s,&common,format,&str::to_owned).unwrap();let patch=parse_settings(ModuleKind::Nametags,&v).unwrap();assert!(patch.issues.is_empty(),"{:?}",patch.issues);let mut actual=Settings::default();for c in patch.changes{if let SettingChange::Nametags(v)=c{v.apply(&mut actual,&["fixture:curse".into()]).unwrap();}}assert_eq!(actual,s);}}
}
